package org.jlinalg.cli;

import java.io.IOException;
import java.nio.file.Path;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class HomerGeneratedSettingsTest {
    @TempDir Path root;
    private Map<String,String> options(String mode)throws Exception{var o=HomerGenomeFixture.options(root);o.remove("background");o.remove("background-format");o.put("background-mode",mode);o.put("generated-admission",root.resolve("admission").toString());o.put("background-randomness","original-unseeded");o.put("background-count-policy","retain-original");o.put("background-overlap","remove-original");if(mode.equals("generated-old")){o.put("background-total","512");o.put("background-boundary-policy","retain-original");}else for(var pair:new String[][]{{"background-count","256"},{"background-candidates","5000"},{"background-bins","1"},{"background-sub-bins","5"},{"background-kmer","2"},{"background-kmer-mode","overall"},{"background-self-overlap","forbid"}})o.put(pair[0],pair[1]);return o;}
    @Test void oldAndNewCommandsKeepDistinctNAndAlgorithmSemantics()throws Exception{var old=options("generated-old");var a=HomerGenomeCli.Plan.read(old).command(old,"5.1");assertEquals("512",a.get(a.indexOf("-N")+1));assertTrue(a.contains("-preparse"));assertTrue(a.contains("-useOldBg"));var newer=options("generated-new");var b=HomerGenomeCli.Plan.read(newer).command(newer,"5.1");assertTrue(b.contains("-useNewBg"));assertFalse(b.contains("-useOldBg"));assertEquals("256",b.get(b.indexOf("-N")+1));assertTrue(b.contains("-ikmer"));assertFalse(b.contains("-bg"));}
    @Test void randomnessAndCountPolicyAreExplicitRequiredDecisions()throws Exception{var o=options("generated-old");o.remove("background-randomness");assertThrows(IllegalArgumentException.class,()->HomerGenomeCli.Plan.read(o));o.put("background-randomness","seeded");assertThrows(IOException.class,()->HomerGenomeCli.Plan.read(o));o.put("background-randomness","original-unseeded");o.remove("background-count-policy");assertThrows(IllegalArgumentException.class,()->HomerGenomeCli.Plan.read(o));}
    @Test void oldOverlapCannotBeSilentlyChangedAcrossVersions()throws Exception{var o=options("generated-old");assertTrue(HomerGeneratedBackground.oldRemovesTargets(o,"5.1"));assertThrows(HomerRuntime.Unavailable.class,()->HomerGeneratedBackground.oldRemovesTargets(o,"4.11"));o.put("background-overlap","retain");assertFalse(HomerGeneratedBackground.oldRemovesTargets(o,"4.11"));assertFalse(HomerGeneratedBackground.oldRemovesTargets(o,"4.11.1"));assertThrows(HomerRuntime.Unavailable.class,()->HomerGeneratedBackground.oldRemovesTargets(o,"5.1"));}
    @Test void newMaskNAndOldWeightChoicesAreNeverIgnored()throws Exception{var o=options("generated-new");o.put("mask-lowercase","yes");assertThrows(HomerRuntime.Unavailable.class,()->HomerGenomeCli.Plan.read(o));o.put("mask-lowercase","no");o.put("maximum-n","0.7");assertThrows(HomerRuntime.Unavailable.class,()->HomerGenomeCli.Plan.read(o));o.put("maximum-n","0.5");o.put("weighting","gc");assertThrows(HomerRuntime.Unavailable.class,()->HomerGenomeCli.Plan.read(o));}
    @Test void modesRejectUnusedSuppliedAndOtherGeneratorOptions()throws Exception{var o=options("generated-new");o.put("background-total","512");assertThrows(IOException.class,()->HomerGenomeCli.Plan.read(o));o.remove("background-total");o.put("background",root.resolve("background.bed").toString());assertThrows(IOException.class,()->HomerGenomeCli.Plan.read(o));}
    @Test void generatedTargetsCanBePreparedWithoutInventingBackgroundRows()throws Exception{var o=options("generated-new");var work=root.resolve("work");java.nio.file.Files.createDirectory(work);var data=HomerGenomeData.targets(o,HomerGenomeCli.Plan.read(o),HomerGenomeData.Limits.read(o),new HomerGenomeRuntime.Context(work,"test","5.1","test",Map.of(),Map.of()),work);assertEquals(2,data.regions().size());assertTrue(data.regions().stream().allMatch(r->r.role().equals("targets")));assertFalse(java.nio.file.Files.exists(work.resolve("stage-background.pos")));data.verify();}
}
